const journal=await readFile('.superpowers/m78-hosted-journey.jsonl','utf8')
check(sha(journal)==='d3301eb226c0cae4428c1e20cde4e2afdcf572b622e96d690cc8c262d6e44058')
const events=journal.trimEnd().split('\n').map(line=>JSON.parse(line)),intent=events[62]
check(events.length===72&&intent.kind==='post_intent'&&intent.data.name==='m78_initial_blocked_inventory'&&intent.data.role==='manager1')
const companyId='8b90c706-1710-494d-b12d-02eef88eacb7',actor='7f0c488a-a645-4a9a-97b1-f043e77322a8'
const {idempotencyKey,...request}=intent.data.request
const backupText=await readFile('.superpowers/m78-actual20-20260922-backup.jsonl','utf8')
check(sha(backupText)==='0ee30fa42dd303502b5b1b974408a75ad00079512c910883be20f45d78dbbbd5')
const backup=JSON.parse(backupText.trimEnd().split('\n')[1]!)
const input=JSON.parse(await Bun.stdin.text())
check(Object.keys(input).sort().join(',')==='operatorDatabaseUrl,operatorId'&&input.operatorId==='/root')
hostedDumpEnvironment(input.operatorDatabaseUrl)
const db=await connectOperator(input.operatorDatabaseUrl)
try{
 const result=await db.transaction(async tx=>{
  await tx.exec('set transaction isolation level repeatable read read only')
  const identity=(await tx.query<any>("select current_database() database,current_user actor,current_setting('transaction_read_only') read_only")).rows[0]
  check(identity.database==='postgres'&&identity.actor==='postgres'&&identity.read_only==='on')
  await canonicalReceipts(tx,21)
  const requests=(await tx.query<any>('select * from neuvetra.scope1_requests where company_id=$1 and idempotency_key=$2',[companyId,idempotencyKey])).rows
  check(requests.length===1,'Expected original request must be reconciled manually if absent')
  const r=requests[0]
  check(r.actor_id===actor&&r.kind==='save'&&r.family==='inventory'&&r.stream_id===null&&r.fingerprint===hash({operation:'save',actor,companyId,family:'inventory',streamId:null,request}))
  const versions=(await tx.query<any>('select * from neuvetra.scope1_versions where company_id=$1 and id=$2',[companyId,r.record_id])).rows
  check(versions.length===1);const v=versions[0],p=v.payload
  check(v.family==='inventory'&&v.version===1&&v.previous_version_id===null&&v.created_by===actor&&p.id===v.id&&p.companyId===companyId&&p.createdBy===actor&&p.version===1&&p.family==='inventory'&&p.previousVersionId===null&&p.previousVersionSha256===null)
  check(hash({...p.activity,expectedVersionId:p.previousVersionId,expectedVersionSha256:p.previousVersionSha256,expectedDependencySha256:p.dependencies.dependencySha256,correctionReason:p.correctionReason})===hash(request))
  check(p.inputSha256===hash(p.activity)&&p.inputSha256===v.input_sha256&&p.contentSha256===hash(m78ContentHashPayload(p))&&p.contentSha256===v.content_sha256&&p.versionSha256===hash(m78VersionHashPayload(p))&&p.versionSha256===v.version_sha256&&hash(JSON.parse(v.export_text))===hash(p))
  const heads=(await tx.query<any>('select * from neuvetra.scope1_heads where company_id=$1',[companyId])).rows
  const audits=(await tx.query<any>('select * from neuvetra.scope1_audit where company_id=$1',[companyId])).rows
  check(heads.length===1&&heads[0].family==='inventory'&&heads[0].id===v.stream_id&&heads[0].version_id===v.id&&heads[0].revision===1)
  check(audits.length===1&&audits[0].kind==='save'&&audits[0].record_id===v.id&&audits[0].record_sha256===v.version_sha256&&audits[0].actor_id===actor)
  const observedInventory=await inventory(tx),observedContent=await content(tx,21)
  const priorEntries=observedContent.entries.filter(e=>!(NEW_TABLES as readonly string[]).includes(e.table))
  sameContent(backup.content,{...observedContent,entries:priorEntries,sha256:hash(priorEntries)},true)
  for(const prior of backup.inventory.tables.filter((t:any)=>t.name!=='schema_migrations')){const current=observedInventory.tables.find(t=>t.name===prior.name);check(current?.count===prior.count&&current?.sha256===prior.sha256)}
  for(const table of NEW_TABLES){const expected=['scope1_heads','scope1_versions','scope1_requests','scope1_audit'].includes(table)?1:0;check(observedInventory.tables.find(t=>t.name===table)?.count===expected)}
  return {status:'m78_timed_out_save_confirmed_committed',createdAt:new Date().toISOString(),project:PROJECT,readOnly:true,identity,journalSha256:sha(journal),intentSequence:63,companyId,actor,request:r,version:v,heads,audits,inventory:observedInventory,content:observedContent,priorContentPreserved:true,applicationWrites:0,authSessionsCreated:0}
 })
